import {createPresenceClient,labels} from './presence.js';
const key='conict-presence-endpoint';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountPCPanel({items,motion,openPanel,panel}){
  const button=document.createElement('button');button.textContent='PC 연결';button.id='pc-button';document.querySelector('.topbar nav').append(button);
  const local= ['127.0.0.1','localhost'].includes(location.hostname),localEndpoint=local?location.origin+'/api/status':'http://127.0.0.1:5178/api/status';
  const seats=items.filter(i=>i.person),ids=seats.map(i=>i.o.seatId);let latest={states:Object.fromEntries(ids.map(id=>[id,'unknown']))},opening=false,assignBusy=false;
  const client=createPresenceClient({seatIds:ids,onChange(data){latest=data;motion.setStates(data.states);const count=Object.values(data.states).filter(s=>s==='online').length,missed=Object.values(data.states).filter(s=>s==='no-response').length,assigned=Object.keys(data.snapshot?.assignments||{}).length;document.querySelector('#scene-note').innerHTML='<span class="dot"></span> '+(data.snapshot?'핑 응답 '+count+' · 미응답 '+missed+' · '+assigned+'자리 연결':'PC 상태 확인 불가')+' <small>모든 구성원 · 각자 3분마다 커피·휴식</small>';if(opening&&panel.open)render()}});
  function render(message=''){
    if(assignBusy)return;
    const snapshot=latest.snapshot,devices=snapshot?.devices?.filter(d=>!d.name?.includes('공유기'))||[];
    openPanel('PC CONNECTION','<h2 id="panel-title">PC와 자리를 연결하세요</h2><p>다른 PC에는 설치·설정을 하지 않습니다. 관찰기를 실행한 컴퓨터에서 응답을 확인합니다.</p><form id="pc-connect"><label for="pc-endpoint">관찰기 주소</label><input id="pc-endpoint" type="url" style="width:100%;padding:12px;margin:8px 0" value="'+esc(latest.endpoint||localEndpoint)+'" required><div class="dialog-actions"><button class="primary" type="submit">관찰기 연결</button><button class="secondary" id="pc-disconnect" type="button">연결 해제</button></div></form><p role="status" id="pc-message">'+esc(message||latest.error||(snapshot?'마지막 확인 '+new Date(snapshot.observedAt).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul'})+' · 자리와 PC를 한 번씩 선택하세요.':'관찰기에 연결하면 후보 기기가 표시됩니다.'))+'</p>'+seats.map(item=>'<label style="display:block;margin:15px 0">'+esc(item.person.name)+' · PC '+esc(labels[latest.states[item.o.seatId]])+'<select data-pc-seat="'+item.o.seatId+'" '+(!snapshot?'disabled':'')+' style="display:block;width:100%;padding:10px;margin-top:5px"><option value="">PC 미지정</option>'+devices.map(d=>'<option value="'+esc(d.ip)+'" '+(snapshot.assignments?.[item.o.seatId]===d.ip?'selected':'')+'>'+esc(d.name||d.ip)+' · '+esc(d.ip)+' · '+esc(labels[d.state]||'미확인')+'</option>').join('')+'</select></label>').join('')+'<p class="disclosure">20초마다 핑 확인 · 모든 구성원은 PC 상태와 관계없이 각자 3분마다 커피·휴식을 다녀온 뒤 자기 자리로 돌아갑니다. 첫 출발 시점은 서로 다르게 분산합니다. 관찰기 오류·오래된 데이터는 PC 확인 불가로 표시합니다. 미응답은 종료·절전·방화벽을 구별하지 못하며 실제 사람의 위치를 뜻하지 않습니다.</p><p class="disclosure">127.0.0.1은 지금 브라우저를 연 컴퓨터입니다. 다른 컴퓨터에서도 같은 상태를 보려면 연구실의 상시 서버 또는 공유기에 접근할 수 있는 별도 수집 경로가 필요합니다.</p><p><a href="./network.html">관찰기 실행 방법과 판정 한계 ↗</a></p>');
    document.querySelector('#pc-connect').onsubmit=e=>{e.preventDefault();try{const value=document.querySelector('#pc-endpoint').value;client.connect(value);try{localStorage.setItem(key,value)}catch{}}catch(e){document.querySelector('#pc-message').textContent=e.message}};
    document.querySelector('#pc-disconnect').onclick=()=>{try{localStorage.removeItem(key)}catch{}client.disconnect()};
    document.querySelectorAll('[data-pc-seat]').forEach(select=>select.onchange=async()=>{assignBusy=true;select.disabled=true;try{const url=new URL(latest.endpoint);url.pathname='/api/assign';url.search='';const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({seatId:select.dataset.pcSeat,ip:select.value}),signal:AbortSignal.timeout(5000)});if(!response.ok)throw new Error('자리 연결을 저장하지 못했습니다. 로컬 관찰기에서 다시 확인하세요.');await client.refresh();assignBusy=false;render('자리 연결을 저장했습니다.')}catch(e){assignBusy=false;render(e.message)}});
  }
  button.onclick=()=>{opening=true;render()};panel.addEventListener('close',()=>opening=false);
  let saved;try{saved=localStorage.getItem(key)}catch{}if(saved){try{client.connect(saved)}catch{}}else if(local)client.connect(localEndpoint);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)void client.refresh()});window.addEventListener('pagehide',()=>client.close());
  return client;
}
